class Company:
    def __init__(self, n):
        self.n = n
        self.boss_of = [None] * (n + 1)
        self.signed_docs = [set() for _ in range(n + 1)]
        self.doc_history = []

    def set_boss(self, x, y):
        self.boss_of[x] = y

    def sign_document(self, x):
        current = x
        while current is not None:
            self.signed_docs[current].add(len(self.doc_history))
            current = self.boss_of[current]
        self.doc_history.append(x)

    def check_signed(self, x, doc_id):
        return doc_id in self.signed_docs[x]


def main():
    n, m = map(int, input().split())
    company = Company(n)

    for _ in range(m):
        event = list(map(int, input().split()))
